window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[238]={"id":"238","numero":238,"titre":"Souffle cardiaque chez l'enfant","objectifs":[{"id":"238-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la sémiologie cardiovasculaire chez l’enfant","contenu":"<p>L'<span class=\"kw-def\">interrogatoire et l'examen clinique</span> en période néonatale et chez le nourrisson permettent de diagnostiquer la majorité des <span class=\"kw-etio\">cardiopathies congénitales</span>. Le souffle est l'élément clé, mais il peut être <span class=\"kw-alerte\">absent même dans des cardiopathies graves</span> (ex. <span class=\"kw-etio\">transposition des gros vaisseaux</span>). À tout âge, rechercher systématiquement : <span class=\"kw-clinique\">cyanose</span>, <span class=\"kw-clinique\">difficultés alimentaires</span>, <span class=\"kw-clinique\">symptomatologie à l'effort</span>.</p>\n\n      <div class=\"callout callout-warn\">\n        <strong>Dogme.</strong> L'<span class=\"kw-alerte\">absence de souffle ne signifie pas cœur normal</span> (cardiomyopathies, ventricule unique, TGV). À l'inverse, l'<span class=\"kw-alerte\">intensité du souffle n'est pas corrélée à la gravité</span> de la maladie sous-jacente.\n      </div>\n\n      <h4>Particularités de l'auscultation</h4>\n      <ul>\n        <li>Enfant calme et rassuré par la présence des parents.</li>\n        <li>Stéthoscope pédiatrique (membrane de <span class=\"kw-clinique\">diamètre</span> adapté).</li>\n        <li>Rythme rapide et souvent irrégulier : l'<span class=\"kw-def\">arythmie sinusale respiratoire</span> est physiologique et peut être marquée → <span class=\"kw-imagerie\">ECG</span> si doute.</li>\n      </ul>\n\n      <h4>Caractériser un souffle</h4>\n      <table >\n        <thead><tr><th>Caractère</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>Timing</td><td><span class=\"kw-clinique\">Systolique</span>, <span class=\"kw-clinique\">diastolique</span> ou <span class=\"kw-clinique\">continu</span> (systolo-diastolique) ; proto-, méso- ou télé-</td></tr>\n          <tr><td>Localisation</td><td>Foyer où le souffle est le mieux perçu</td></tr>\n          <tr><td>Timbre</td><td>Aigu, grave, <span class=\"kw-clinique\">doux</span>, <span class=\"kw-clinique\">râpeux</span>, aspiratif, humide, sec, rude…</td></tr>\n          <tr><td>Intensité (1 à 6)</td><td><span class=\"kw-chiffre\">1</span> difficilement audible ; <span class=\"kw-chiffre\">2</span> léger mais immédiat ; <span class=\"kw-chiffre\">3</span> très distinct sur faible surface ; <span class=\"kw-chiffre\">4</span> très distinct sur large surface ; <span class=\"kw-chiffre\">5</span> <span class=\"kw-clinique\">frémissant</span> ; <span class=\"kw-chiffre\">6</span> audible stéthoscope décollé</td></tr>\n          <tr><td><span class=\"kw-clinique\">Irradiation</span></td><td>Espace de diffusion où le souffle reste entendu</td></tr>\n          <tr><td>Signes associés</td><td><span class=\"kw-clinique\">Clicks valvulaires</span> ; <span class=\"kw-clinique\">dédoublement constant du B2</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Six foyers d'auscultation :</strong> pulmonaire, aortique, tricuspidien (xiphoïde), mitral (apex), sous-claviculaire gauche, interscapulaire gauche (dos).</p>\n      <p><strong>Bruits physiologiques :</strong> <span class=\"kw-clinique\">dédoublement du B2</span> le long du bord sternal gauche, variable avec la respiration (inspiratoire) ; <span class=\"kw-clinique\">B3 apexien</span> fréquent (<span class=\"kw-chiffre\">50 %</span> des cas), mais parfois pathologique.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Drapeaux rouges</span> — excluent le souffle fonctionnel.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Souffle diastolique</span> → jamais fonctionnel.</li>\n          <li><span class=\"kw-alerte\">Souffle holosystolique</span> → <span class=\"kw-etio\">CIV</span>, insuffisance mitrale.</li>\n          <li><span class=\"kw-alerte\">Souffle frémissant, tonalité râpeuse</span> → obstacle valvulaire (aortique/pulmonaire).</li>\n          <li><span class=\"kw-alerte\">Intensité maximale au bord gauche du thorax</span> (≠ sternum) → <span class=\"kw-etio\">coarctation</span>.</li>\n          <li><span class=\"kw-alerte\">Dédoublement fixe et constant du B2</span> → <span class=\"kw-etio\">CIA</span>, BBD.</li>\n          <li><span class=\"kw-alerte\">Éclat du B2</span> bord sternal gauche → HTAP, malposition des gros vaisseaux.</li>\n          <li><span class=\"kw-alerte\">Click systolique</span> : mésosystolique apexien (prolapsus mitral) ; protosystolique (sténose valvulaire d'un gros vaisseau).</li>\n        </ul>\n      </div>\n\n      <h4>Examen cardiovasculaire complet</h4>\n      <table >\n        <thead><tr><th>Élément</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td>Signes fonctionnels</td><td>Souvent absents (découverte fortuite). <strong><span class=\"kw-clinique\">Dyspnée</span> d'effort</strong> = symptôme le plus commun ; malaises rarement cardiaques (spasme du sanglot, <span class=\"kw-clinique\">malaise</span> vagal) ; douleur thoracique exceptionnellement cardiaque.<br><strong>À l'effort</strong> (douleurs, syncopes, <span class=\"kw-clinique\">palpitations</span>) → obstacle voie gauche (<span class=\"kw-etio\">sténose aortique</span>, <span class=\"kw-etio\">CMH obstructive</span>), anomalies coronaires (<span class=\"kw-etio\">Kawasaki</span>), troubles du rythme héréditaires (<span class=\"kw-etio\">QT long/court</span>, <span class=\"kw-alerte\">TV</span> catécholergique, BAV <span class=\"kw-etio\">congénital</span>, Brugada)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Cyanose</span></td><td>SaO₂ normale <span class=\"kw-chiffre\">&gt; 96 %</span> ; <span class=\"kw-alerte\">cyanose si &lt; 85 %</span> à l'oxymétrie ; <span class=\"kw-clinique\">hippocratisme digital</span> si prolongée.<br><strong>Cause respiratoire :</strong> hypoxie <span class=\"kw-clinique\">répond à l'O₂</span><br><strong>Cause cardiaque</strong> (shunt droite-gauche, malconnexion) : <span class=\"kw-alerte\">hypoxie réfractaire à l'O₂</span></td></tr>\n          <tr><td><span class=\"kw-ci\">Insuffisance cardiaque</span></td><td>Moins typique que chez l'adulte. <span class=\"kw-clinique\">Polypnée</span>, <span class=\"kw-clinique\">tirage</span>, <span class=\"kw-clinique\">toux</span> ; difficultés alimentaires, <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">stagnation pondérale</span> ; <span class=\"kw-clinique\">tachycardie</span> ; <strong><span class=\"kw-clinique\">hépatomégalie</span> = marqueur constant</strong> (un débord de <span class=\"kw-chiffre\">1 à 2 cm</span> reste normal à cet âge) ; TJ / RHJ moins marqués ; <span class=\"kw-clinique\">OMI rares</span></td></tr>\n          <tr><td>Pouls</td><td><strong>Mal perçus aux 4 membres :</strong> insuffisance circulatoire, <span class=\"kw-etio\">sténose aortique sévère</span><br><strong>MS mieux perçus que fémoraux :</strong> <span class=\"kw-etio\">coarctation de l'aorte</span><br><strong>Bondissants :</strong> large <span class=\"kw-etio\">PCA</span>, insuffisance aortique sévère</td></tr>\n          <tr><td>Pression artérielle</td><td><span class=\"kw-alerte\">Gradient &gt; 20 mmHg</span> (MS &gt; MI) → <span class=\"kw-etio\">coarctation</span> ; toute <span class=\"kw-clinique\">HTA de l'enfant</span> impose la recherche d'une cause secondaire (néphro/endocrino, mais aussi coarctation)</td></tr>\n          <tr><td>Frémissement (thrill)</td><td>Frémissement précordial ou sus-sternal = <span class=\"kw-alerte\">toujours pathologique</span></td></tr>\n          <tr><td>Auscultation pulmonaire</td><td><span class=\"kw-clinique\">Crépitants</span> si hypervascularisation (shunt G-D large) ou pathologie du cœur gauche</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Circonstances de découverte selon l'âge</h4>\n      <table >\n        <thead><tr><th>Âge</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td>Nouveau-né</td><td><span class=\"kw-clinique\">Cyanose</span> et/ou <span class=\"kw-clinique\">insuffisance cardiaque</span></td></tr>\n          <tr><td>Nourrisson</td><td><span class=\"kw-clinique\">Cyanose</span>, IC ; <span class=\"kw-clinique\">difficultés alimentaires</span> (tétées longues, sudation, endormissement) ; <span class=\"kw-clinique\">retard staturo-pondéral</span> ; <span class=\"kw-clinique\">polypnée</span> ; infections pulmonaires à répétition</td></tr>\n          <tr><td>Enfant plus grand</td><td><span class=\"kw-clinique\">Dyspnée d'effort</span>, fat<span class=\"kw-chiffre\">iga</span>bilité, rarement <span class=\"kw-clinique\">syncope</span> ; <span class=\"kw-clinique\">douleur thoracique d'effort</span> (obstacle éjection VG) ; <span class=\"kw-clinique\">AEG</span> (anorexie, asthénie, douleurs abdominales)</td></tr>\n          <tr><td>Signes extracardiaques</td><td><span class=\"kw-alerte\">AVC</span>, <span class=\"kw-clinique\">fièvre</span> au long cours, cassure de la courbe pondérale</td></tr>\n          <tr><td>Contexte particulier</td><td>Syndrome polymalformatif (<span class=\"kw-clinique\">dysmorphie faciale</span>, anomalie des extrémités/OGE) → <span class=\"kw-imagerie\">échocardiographie systématique</span> même sans souffle ; maladie <span class=\"kw-etio\">génétique</span> familiale (<span class=\"kw-etio\">Marfan</span>) ; cardiopathie <span class=\"kw-etio\">congénitale</span> chez un apparenté du 1ᵉʳ degré</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Syndromes génétiques associés à une cardiopathie</h4>\n      <table >\n        <thead><tr><th>Syndrome</th><th>Cardiopathie associée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Trisomie 21</span></td><td>Cardiopathie dans <span class=\"kw-chiffre\">1 cas sur 2</span>, dont <span class=\"kw-chiffre\">50 %</span> de <span class=\"kw-etio\">canal atrioventriculaire (CAV)</span> ; aussi <span class=\"kw-etio\">Fallot</span>, <span class=\"kw-etio\">CIV</span>, <span class=\"kw-etio\">CIA</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Syndrome de Turner</span> (45,X0)</td><td>Risque accru de <span class=\"kw-etio\">coarctation de l'aorte</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Syndrome de Di George</span> (del 22q11)</td><td>Cardiopathies fréquentes, surtout la <span class=\"kw-etio\">tétralogie de Fallot</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Syndrome de Marfan</span></td><td>Dilatation / anévrisme / <span class=\"kw-alerte\">rupture</span> de l'<span class=\"kw-clinique\">aorte ascendante</span> ; insuffisance aortique ou mitrale</td></tr>\n          <tr><td>Autres</td><td><span class=\"kw-etio\">Williams-Beuren</span> (del 7), <span class=\"kw-etio\">Noonan</span>, <span class=\"kw-etio\">CHARGE</span></td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 45 — Maladies génétiques · 234 — <span class=\"kw-ci\">Insuffisance cardiaque</span></em></p>","frequence":0},{"id":"238-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un souffle cardiaque organique et non organique","contenu":"<p>La découverte d'un souffle cardiaque est une situation <span class=\"kw-def\">très fréquente</span> chez l'enfant. Premier enjeu : distinguer le <span class=\"kw-def\">souffle fonctionnel</span> du <span class=\"kw-def\">souffle organique</span>.</p>\n\n      <table >\n        <thead><tr><th>Type</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Souffle fonctionnel</span> (le plus fréquent)</td><td>Résulte de <span class=\"kw-def\">turbulences de l'écoulement normal</span> du sang à travers le cœur et <span class=\"kw-clinique\">les</span> vaisseaux. Disparaît le plus souvent quand l'enfant grandit (<strong>abstention thérapeutique</strong>), peut parfois persister à l'âge adulte. Synonymes : innocent, bénin, anorganique.</td></tr>\n          <tr><td><span class=\"kw-def\">Souffle organique</span> (plus rare)</td><td>Créé par une <span class=\"kw-alerte\">anomalie morphologique cardiaque</span>, le plus souvent <span class=\"kw-etio\">congénitale</span>. Un souffle intense traduit un <span class=\"kw-def\">gradient de pression anormal</span> : entre 2 cavités (ex. petite <span class=\"kw-etio\">CIV</span> entre VG et VD) ou entre 2 parties d'un vaisseau (ex. <span class=\"kw-etio\">coarctation</span>, sténose de branche pulmonaire).</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Épidémiologie</span> et orientation selon l'âge</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Malformation cardiaque congénitale</span> : <span class=\"kw-chiffre\">1 %</span> des enfants à la naissance.</li>\n        <li><span class=\"kw-def\">Souffle fonctionnel</span> : <span class=\"kw-chiffre\">30-50 %</span> des enfants d'âge scolaire.</li>\n        <li>Nourrisson : <span class=\"kw-chiffre\">90 %</span> des souffles sont <span class=\"kw-alerte\">organiques</span> (cardiopathies congénitales diagnostiquées au 1ᵉʳ mois, <span class=\"kw-chiffre\">95 %</span> avant <span class=\"kw-chiffre\">4 ans</span>).</li>\n        <li>Enfant d'âge scolaire : <span class=\"kw-chiffre\">50 %</span> des souffles sont <span class=\"kw-def\">fonctionnels</span>.</li>\n        <li><span class=\"kw-etio\">Cardiomyopathie</span>, <span class=\"kw-etio\">myocardite aiguë</span> : rarement à l'origine d'un souffle ; valvulopathies rhumatismales exceptionnelles en Occident.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-clinique\">Les</span> dogmes.</strong>\n        <ul>\n          <li>Absence de souffle ≠ cœur normal (cardiomyopathies, ventricule unique).</li>\n          <li>Un souffle intense peut traduire une cardiopathie peu sévère (petite CIV).</li>\n          <li><span class=\"kw-alerte\">Un souffle diastolique n'est JAMAIS fonctionnel.</span></li>\n          <li>Un souffle <span class=\"kw-clinique\">variable dans le temps ± selon la position</span> est <span class=\"kw-clinique\">quasi-toujours fonctionnel</span>.</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Au moindre doute.</strong> Le 1ᵉʳ enjeu chez un enfant avec souffle est de distinguer fonctionnel ↔ organique. Au moindre doute → <span class=\"kw-imagerie\">échocardiographie</span> par un cardiopédiatre expérimenté.\n      </div>\n\n      <h4>Le souffle fonctionnel — caractéristiques</h4>\n      <ul>\n        <li><strong>Temps :</strong> bref, <span class=\"kw-clinique\">éjectionnel</span>, proto- ou mésosystolique (<span class=\"kw-alerte\">jamais diastolique, jamais holosystolique</span>).</li>\n        <li><strong>Intensité :</strong> faible (<span class=\"kw-chiffre\">&lt; 3/6</span>), <span class=\"kw-clinique\">non frémissant</span>, souvent variable avec la position.</li>\n        <li><strong>Timbre :</strong> <span class=\"kw-clinique\">doux</span>, parfois musical.</li>\n        <li><strong>Variabilité :</strong> diminue à l'<span class=\"kw-clinique\">orthostatisme</span> / au repos ; augmente avec <span class=\"kw-clinique\">fièvre</span>, effort, anémie.</li>\n        <li><strong>Localisation :</strong> endapexienne (3-4ᵉ EIG) ou foyer pulmonaire ; peu / pas d'<span class=\"kw-clinique\">irradiation</span>.</li>\n        <li><strong>Auscultation :</strong> <span class=\"kw-clinique\">B1-B2 normaux</span>, <span class=\"kw-clinique\">diastole libre</span> ; examen CV normal, pas de symptôme.</li>\n      </ul>\n\n      <h4><span class=\"kw-clinique\">Les</span> 6 souffles anorganiques</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Cycle</th><th>Localisation</th><th>Caractéristique</th></tr></thead>\n        <tbody>\n          <tr><td>Musical / vibratoire</td><td><span class=\"kw-clinique\">Systolique</span></td><td>Endapex</td><td>Bref, piaulant</td></tr>\n          <tr><td>Pulmonaire</td><td><span class=\"kw-clinique\">Systolique</span></td><td>Foyer pulmonaire</td><td>B2 normal ou dédoublement variable</td></tr>\n          <tr><td>Carotidien</td><td><span class=\"kw-clinique\">Systolique</span></td><td>Base du cou</td><td>Diminué par la compression carotidienne</td></tr>\n          <tr><td>Veineux (« hum »)</td><td><span class=\"kw-clinique\">Continu</span></td><td>Sous-claviculaire</td><td>Diminué par la compression jugulaire</td></tr>\n          <tr><td>De branche pulmonaire</td><td><span class=\"kw-clinique\">Systolique</span></td><td>Foyer pulmonaire / aisselles</td><td>Nouveau-né &lt;<span class=\"kw-chiffre\"> 3 mois</span>, disparaît à<span class=\"kw-chiffre\"> 4-6 mois</span></td></tr>\n          <tr><td>Cardiorespiratoire</td><td>Protosystolique</td><td>Endapex</td><td>Disparaît en expiration</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Circonstances favorisantes :</strong> augmentation du débit (<span class=\"kw-etio\">fièvre</span>, <span class=\"kw-etio\">effort</span>, émotion, <span class=\"kw-etio\">anémie</span>, <span class=\"kw-etio\">hyperthyroïdie</span>) ; anomalies morphologiques (dos plat, thorax en entonnoir, scoliose).</p>\n\n      <div class=\"callout callout-info\">\n        <strong>PEC du souffle fonctionnel.</strong> <span class=\"kw-clinique\">Rassurer la famille</span> ; <span class=\"kw-clinique\">aucune surveillance</span> ni <span class=\"kw-clinique\">restriction sportive</span> nécessaire ; peut disparaître à l'adolescence ou persister à l'âge adulte.\n      </div>","frequence":1},{"id":"238-3","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les apports des examens de première intention devant un souffle de l’enfant","contenu":"<h4>Quand demander une expertise cardiopédiatrique ?</h4>\n      <ul>\n        <li>Présence d'une <span class=\"kw-alerte\">anomalie à l'examen clinique</span>.</li>\n        <li>Avant l'âge de <span class=\"kw-chiffre\">&lt; 1 an</span> : <strong>systématique</strong>, même pour un souffle isolé → <span class=\"kw-imagerie\">échographie cardiaque</span>.</li>\n        <li>Après <span class=\"kw-chiffre\">&gt; 1 an</span> : un souffle isolé est le plus souvent <span class=\"kw-def\">fonctionnel</span>.</li>\n      </ul>\n\n      <h4>Orientation diagnostique selon l'âge</h4>\n      <table >\n        <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td>Nouveau-né / nourrisson &lt;<span class=\"kw-chiffre\"> 1 an</span><br>(souffle souvent organique)</td><td><strong>Avec signes associés</strong> (<span class=\"kw-clinique\">cyanose</span>, IC, polypnée) → <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-alerte\">réanimation</span> + cardiopédiatrie)<br><strong>Souffle isolé du nouveau-né</strong> → <span class=\"kw-imagerie\">échocardiographie avant sortie de maternité</span> (ou avant J8)<br><strong>Souffle isolé du nourrisson</strong> → avis cardiopédiatrique + <span class=\"kw-imagerie\">échocardiographie</span></td></tr>\n          <tr><td>Enfant &gt;<span class=\"kw-chiffre\"> 1 an</span><br>(souffle souvent fonctionnel)</td><td><strong>Caractéristiques fonctionnelles</strong> → <span class=\"kw-clinique\">simple surveillance</span>, pas d'avis<br><strong>Caractéristiques non fonctionnelles ou contexte familial</strong> → avis cardiopédiatrique<br><strong>Souffle non isolé + signes associés</strong> → <span class=\"kw-alerte\">avis urgent</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Examens de <span class=\"kw-chiffre\">première intention</span></h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Apports et limites</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">ECG</span></td><td>Différent de l'adulte, varie avec l'âge : <span class=\"kw-clinique\">FC d'autant plus rapide que l'enfant est jeune</span>, axe QRS plus droit, <span class=\"kw-clinique\">PR</span> plus court. <strong>Ondes T <span class=\"kw-imagerie\">négatives de V1 à V4</span></strong> durant l'enfance (positives à la naissance, se négativent vers la fin de la 5ᵉ semaine). <span class=\"kw-clinique\">Arythmie</span> sinusale respiratoire banale.<br><span class=\"kw-alerte\">Un tracé normal est rassurant mais n'écarte pas</span> une anomalie mineure (petite CIV/CIA, fuite ou sténose de faible degré).</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Radiographie thoracique</span></td><td><strong>Cardiomégalie :</strong> oriente sans préciser la nature (méfiance « <span class=\"kw-alerte\">fausses cardiomégalies</span> » par superposition du <span class=\"kw-clinique\">thymus</span>)<br><strong>Saillie de l'arc moyen gauche :</strong> dilatation du tronc de l'AP (shunt G-D)<br><strong>Arc moyen concave :</strong> hypoplasie de la voie pulmonaire (ex. <span class=\"kw-etio\">T4F</span>)<br><strong>Pédicule étroit :</strong> anomalie de position des gros vaisseaux<br><strong>Vascularisation :</strong> <span class=\"kw-radio\">hyper</span> (hyperdébit, shunt G-D) <span class=\"kw-bio\">vs</span> <span class=\"kw-radio\">hypo</span> (obstacle voie pulmonaire)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">ETT</span> (<span class=\"kw-imagerie\">échocardiographie transthoracique</span>)</td><td><strong>Examen clé du diagnostic</strong> : porte en règle un <span class=\"kw-def\">diagnostic précis</span>, qualité constamment bonne chez l'enfant (parfois gênée par l'agitation)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Examens de seconde intention</h4>\n      <ul>\n        <li><strong><span class=\"kw-imagerie\">Épreuve d'effort</span></strong> (tapis roulant chez le petit, bicyclette ergométrique).</li>\n        <li><strong><span class=\"kw-imagerie\">Holter</span> <span class=\"kw-imagerie\">ECG</span></strong> : troubles du rythme idiopathiques ou postopératoires.</li>\n        <li><strong><span class=\"kw-imagerie\">IRM cardiaque</span></strong> : très performante pour <span class=\"kw-clinique\">les</span> gros vaisseaux intrathoraciques.</li>\n        <li><strong><span class=\"kw-imagerie\">TDM multibarrette</span></strong> : examen <span class=\"kw-alerte\">irradiant</span> (à l'inverse de l'<span class=\"kw-imagerie\">IRM</span>).</li>\n        <li><strong><span class=\"kw-bio\">Biologie</span></strong> (<span class=\"kw-bio\">troponine</span>, <span class=\"kw-bio\">BNP</span>) : <span class=\"kw-alerte\">sans intérêt</span> dans l'évaluation initiale, utile pour le <span class=\"kw-def\">suivi</span> d'une cardiopathie <span class=\"kw-etio\">congénitale</span>.</li>\n        <li><strong>Cathétérisme cardiaque</strong> : indications limitées (<span class=\"kw-def\">bilan préopératoire</span> des cardiopathies complexes, ou cathétérisme interventionnel thérapeutique) ; sous AG avant <span class=\"kw-chiffre\">10 ans</span>.</li>\n      </ul>","frequence":0},{"id":"238-4","rang":"B","rubrique":"Étiologies","titre":"Connaître l’orientation étiologique des souffles cardiaques","contenu":"<h4><span class=\"kw-def\">Classification</span> des cardiopathies congénitales</h4>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Cardiopathies</th></tr></thead>\n        <tbody>\n          <tr><td>Shunts gauche-droit</td><td><span class=\"kw-etio\">CIV</span> ; <span class=\"kw-etio\">CIA</span> ; <span class=\"kw-etio\">PCA</span> ; <span class=\"kw-etio\">CAVC</span></td></tr>\n          <tr><td>Obstacles du cœur droit</td><td><span class=\"kw-etio\">Tétralogie de Fallot (T4F)</span> ; <span class=\"kw-etio\">sténose valvulaire pulmonaire (SVP)</span></td></tr>\n          <tr><td>Obstacles du cœur gauche</td><td><span class=\"kw-etio\">Coarctation aortique</span> ; <span class=\"kw-etio\">rétrécissement aortique congénital</span> ; <span class=\"kw-etio\">bicuspidie aortique</span> (cardiopathie congénitale la plus fréquente — <span class=\"kw-chiffre\">1-2 %</span> de la population — souffle systolique éjectionnel au foyer aortique de l'enfant/adolescent ; expose au RA précoce, à l'IA, à l'endocardite et à la dilatation de l'aorte ascendante)</td></tr>\n          <tr><td>Malconnexions</td><td><span class=\"kw-etio\">Transposition des gros vaisseaux (TGV)</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Pas de diagnostic anténatal de CIA ni de PCA.</strong> La <span class=\"kw-etio\">CIA</span> (communication inter-atriale) et la <span class=\"kw-etio\">PCA</span> (persistance du canal artériel) sont <span class=\"kw-def\">physiologiques in utero</span> (foramen ovale + canal artériel perméables à l'état normal) : leur diagnostic ne peut donc pas être posé avant la naissance.\n      </div>\n\n      <h4>Cyanogènes <span class=\"kw-bio\">vs</span> non-cyanogènes</h4>\n      <table >\n        <thead><tr><th>Cyanogènes</th><th>Non-cyanogènes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Tétralogie de Fallot</span> ; <span class=\"kw-etio\">transposition des gros vaisseaux</span> ; (sténose/atrésie pulmonaire avec shunt intracardiaque, atrésie tricuspide, tronc artériel commun, Ebstein, Eisenmenger, cœur univentriculaire)</td>\n            <td><span class=\"kw-etio\">CIA</span> (pas à risque d'EI) ; <span class=\"kw-etio\">CIV</span> ; <span class=\"kw-etio\">CAV</span> ; <span class=\"kw-etio\">PCA</span> ; <span class=\"kw-etio\">coarctation</span> ; <span class=\"kw-etio\">rétrécissement aortique</span> ; <span class=\"kw-etio\">sténose AP</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Si non opérée → cardiopathie à haut risque d'endocardite infectieuse → antibioprophylaxie</span></td>\n            <td>Pas d'<span class=\"kw-ttt\">antibioprophylaxie</span> systématique</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Sémiologie des souffles organiques</h4>\n      <table >\n        <thead><tr><th>Cardiopathie</th><th>Temps</th><th>Localisation / <span class=\"kw-clinique\">irradiation</span></th><th>Signe associé / apparition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">CIV</span></td><td><span class=\"kw-clinique\">Holosystolique</span></td><td>Endapexien (parasternal G), foyer tricuspide ; <span class=\"kw-clinique\">irradiation</span> en « rayon de roue »</td><td><span class=\"kw-clinique\">Frémissant</span> ; apparaît à <span class=\"kw-chiffre\">quelques jours</span> de vie</td></tr>\n          <tr><td><span class=\"kw-etio\">CIA</span></td><td><span class=\"kw-clinique\">Systolique</span></td><td>Foyer pulmonaire ; creux axillaire + dos</td><td><span class=\"kw-alerte\">Dédoublement fixe et constant du B2</span> ; 1ᵉʳˢ mois de vie</td></tr>\n          <tr><td><span class=\"kw-etio\">PCA</span></td><td><span class=\"kw-clinique\">Continu</span> (systolo-diastolique)</td><td>Sous-claviculaire gauche</td><td>Apparaît à quelques jours de vie (pas à la naissance)</td></tr>\n          <tr><td><span class=\"kw-etio\">SVP</span></td><td><span class=\"kw-clinique\">Systolique</span></td><td>Foyer pulmonaire ; dos</td><td>Timbre <span class=\"kw-clinique\">râpeux</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Coarctation</span></td><td><span class=\"kw-clinique\">Systolique</span></td><td>Bord gauche du thorax (≠ sternum) ; dos, sous-clav. G</td><td><span class=\"kw-clinique\">Frémissement sus-sternal</span> ; quelques jours de vie</td></tr>\n          <tr><td><span class=\"kw-etio\">RAo</span></td><td>Mésosystolique (losangique)</td><td>Foyer aortique ; vaisseaux du cou</td><td><span class=\"kw-clinique\">Râpeux, rude</span> ; gravité = abolition B2, <span class=\"kw-clinique\">B3</span> (B4 possible, non grave)</td></tr>\n          <tr><td><span class=\"kw-etio\">IM</span></td><td><span class=\"kw-clinique\">Holosystolique</span> (rectangulaire)</td><td>Foyer mitral (apex) ; <span class=\"kw-clinique\">irradiation</span> à l'aisselle (base du cœur si prolapsus postérieur)</td><td>Doux, « jet de vapeur » ; <span class=\"kw-clinique\">pas de B4</span> ; gravité = <span class=\"kw-alerte\">galop protodiastolique (B3)</span>, éclat B2 si <span class=\"kw-clinique\">HTP</span></td></tr>\n          <tr><td><span class=\"kw-etio\">IA</span></td><td>Proto-mésodiastolique (decrescendo)</td><td>Foyer aortique ; le long du bord gauche du sternum</td><td>Doux, aspiratif ; gravité = souffle holodiastolique, <span class=\"kw-alerte\">galop B3</span>, <span class=\"kw-alerte\">roulement de Flint</span> apexien</td></tr>\n          <tr><td><span class=\"kw-etio\">RM</span></td><td><span class=\"kw-clinique\">Diastolique</span></td><td>Foyer mitral</td><td>Roulement diastolique ; éclat du B1 si valve souple ; dédoublement B2 si HTAP (<span class=\"kw-clinique\">rythme de Durozier</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\">T4F</span></td><td colspan=\"3\">Souffle de la <span class=\"kw-etio\">sténose pulmonaire</span> (± souffle de CIV) — systolique intense au foyer pulmonaire</td></tr>\n          <tr><td><span class=\"kw-etio\">TGV</span></td><td colspan=\"3\"><span class=\"kw-alerte\">Pas de souffle</span> — <span class=\"kw-clinique\">cyanose</span> réfractaire isolée</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-source\"><em>IM, IA et RM sont des valvulopathies (le plus souvent acquises) — détaillées à l'item 233. Listées ici car elles entrent dans le <span class=\"kw-def\">diagnostic différentiel</span> auscultatoire des souffles.</em></p>\n\n      <h4>Orientation selon la localisation du souffle</h4>\n      <table >\n        <thead><tr><th>Foyer / <span class=\"kw-clinique\">irradiation</span></th><th>Évoque</th></tr></thead>\n        <tbody>\n          <tr><td>Foyer pulmonaire</td><td><span class=\"kw-etio\">Sténose pulmonaire</span>, <span class=\"kw-etio\">CIA</span></td></tr>\n          <tr><td>Xiphoïde</td><td><span class=\"kw-etio\">CIV</span></td></tr>\n          <tr><td>Foyer aortique</td><td><span class=\"kw-etio\">Sténose aortique</span>, sténose de l'AP droite</td></tr>\n          <tr><td>Dos</td><td><span class=\"kw-etio\">Coarctation</span>, sténose de branche pulmonaire</td></tr>\n          <tr><td><span class=\"kw-clinique\">Irradiation</span> « rayon de roue »</td><td><span class=\"kw-etio\">CIV</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Irradiation</span> au cou</td><td><span class=\"kw-etio\">Sténose aortique</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Principales cardiopathies en détail</h4>\n      <table >\n        <thead><tr><th>Cardiopathie</th><th>Points clés</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">CIV</span></td><td>Shunt <span class=\"kw-def\">VG → VD → AP</span>, surcharge poumons + cavités gauches. Cause la plus fréquente chez le nouveau-né à terme. Petite/moyenne = peu symptomatique ; large = <span class=\"kw-clinique\">IC</span>. <span class=\"kw-alerte\">Pas de cyanose.</span> <span class=\"kw-imagerie\">RXT</span> : cardiomégalie + hypervascularisation si large.</td></tr>\n          <tr><td><span class=\"kw-etio\">CIA</span></td><td><strong>2ᵉ cardiopathie <span class=\"kw-etio\">congénitale</span> la plus fréquente</strong> (prédominance féminine 2:1). Shunt G-D pré-tricuspidien. <span class=\"kw-clinique\">Asymptomatique ++</span> ; <span class=\"kw-alerte\">dédoublement fixe du B2</span>. Complications après <span class=\"kw-chiffre\">30 ans</span> (IC droite, troubles du rythme SV, HTAP).</td></tr>\n          <tr><td><span class=\"kw-etio\">PCA</span></td><td>Shunt <span class=\"kw-def\">Ao → AP</span>. <span class=\"kw-def\">Terrain</span> <span class=\"kw-clinique\">prématuré ++</span>. Souffle <span class=\"kw-clinique\">continu</span> sous-claviculaire G, <span class=\"kw-clinique\">pouls amples / bondissants</span>. Large = IC, infections respiratoires récidivantes.</td></tr>\n          <tr><td><span class=\"kw-etio\">Tétralogie de Fallot</span></td><td><strong>4 critères :</strong> sténose infundibulaire pulmonaire ; <span class=\"kw-clinique\">HVD</span> ; dextroposition aortique ; <span class=\"kw-etio\">CIV</span> avec aorte à cheval.<br><strong>Cardiopathie cyanogène la plus fréquente</strong> (<span class=\"kw-clinique\">cyanose</span> retardée). T4F rose (peu serrée, asymptomatique) <span class=\"kw-bio\">vs</span> <span class=\"kw-alerte\">T4F bleue</span> (cyanose réfractaire, <span class=\"kw-clinique\">hippocratisme digital</span>, <span class=\"kw-clinique\">squatting / accroupissement</span>). <span class=\"kw-imagerie\">RXT</span> : cœur <span class=\"kw-radio\">en sabot</span>. Correction chirurgicale entre <span class=\"kw-chiffre\">6 mois</span> et <span class=\"kw-chiffre\">1 an</span>.</td></tr>\n          <tr><td><span class=\"kw-etio\">SVP</span></td><td>Obstacle à l'éjection du VD → HVD. <span class=\"kw-clinique\">Souffle systolique</span> au foyer pulmonaire (d'autant plus intense que serré). Forme <span class=\"kw-alerte\">critique du nouveau-né</span> : <span class=\"kw-clinique\">cyanose</span> réfractaire se majorant à la fermeture du canal artériel. <span class=\"kw-imagerie\">RXT</span> : arc moyen convexe (dilatation post-sténotique).</td></tr>\n          <tr><td><span class=\"kw-etio\">Rétrécissement aortique (Rao)</span></td><td>Obstacle à l'éjection du VG → HVG. <span class=\"kw-clinique\">Souffle systolique</span> foyer aortique, <span class=\"kw-clinique\">pouls pincés</span> si serré. Nouveau-né avec Rao sévère : <span class=\"kw-alerte\">choc cardiogénique à la fermeture du canal artériel</span>.</td></tr>\n          <tr><td><span class=\"kw-etio\">Coarctation aortique</span></td><td><span class=\"kw-clinique\">Gradient tensionnel MS &gt; MI</span>, <span class=\"kw-clinique\">abolition des pouls</span> fémoraux. Forme préductale = forme grave néonatale avec IC.</td></tr>\n          <tr><td><span class=\"kw-etio\">TGV</span></td><td>Aorte naît du VD, AP du VG (circulations en parallèle — survie dépend du <span class=\"kw-clinique\">foramen ovale</span> + <span class=\"kw-clinique\">canal artériel</span>). <span class=\"kw-alerte\">Cyanose réfractaire isolée à la naissance, sans souffle.</span> <span class=\"kw-imagerie\">RXT</span> : pas de cardiomégalie.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-clinique\">Malaise</span> de Fallot — <span class=\"kw-alerte\">urgence</span>.</strong> Complication aiguë de la <span class=\"kw-etio\">T4F</span> : survient sur une <span class=\"kw-clinique\">tachycardie</span> (pleurs, effort) → majoration de l'obstacle sous-valvulaire pulmonaire → ↑ du shunt droite-gauche par la CIV → <span class=\"kw-alerte\">cyanose majeure</span>. Urgence médicale voire chirurgicale.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Transition néonatale.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">résistances pulmonaires</span> restent élevées les 1ᵉʳˢ jours : les <span class=\"kw-etio\">shunts gauche-droit</span> ne s'expriment souvent qu'après un délai. Risque d'<span class=\"kw-alerte\">HTAP irréversible si shunt opéré trop tard</span> → impératif d'<strong>opérer avant <span class=\"kw-chiffre\">1 an</span></strong>.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-ttt\">Antibioprophylaxie</span> de l'<span class=\"kw-clinique\">endocardite</span>.</strong> Lors des gestes dentaires à risque : <span class=\"kw-etio\">cardiopathie cyanogène</span> ; dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span> suivant la fermeture d'un shunt par patch/prothèse (ou au-delà si shunt résiduel).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"kw-clinique\">Endocardite</span> infectieuse · 233 — Valvulopathie · 234 — <span class=\"kw-ci\">Insuffisance cardiaque</span></em></p>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/tetralogy-of-fallot","label":"Radiopaedia : Tetralogy of Fallot"},{"href":"https://radiopaedia.org/articles/pulmonary-valve-stenosis","label":"Radiopaedia : Pulmonary valve stenosis"},{"href":"https://radiopaedia.org/articles/ventricular-septal-defect-1","label":"Radiopaedia : Ventricular septal defect"},{"href":"https://radiopaedia.org/articles/atrial-septal-defect-2","label":"Radiopaedia : Atrial septal defect"},{"href":"https://radiopaedia.org/articles/patent-ductus-arteriosus","label":"Radiopaedia : Patent ductus arteriosus"},{"href":"https://radiopaedia.org/articles/transposition-of-the-great-arteries","label":"Radiopaedia : Transposition of the great arteries"},{"href":"https://fr.wikipedia.org/wiki/Hypertension_art%C3%A9rielle_pulmonaire","label":"Wikipédia : Hypertension artérielle pulmonaire"},{"href":"https://fr.wikipedia.org/wiki/Syndrome_d%27Eisenmenger","label":"Wikipédia : Syndrome d’Eisenmenger"}]}],"astuces":[{"type":"info","titre":"Astuces & pièges et stratégie","contenu":"<p>Couches « Astuces de PU & Pièges » et « Stratégie &amp; CAT » : à compléter après revue clinique.</p>"}],"strategie":{"urgence":"<p><strong>Nouveau-né / nourrisson &lt;<span class=\"kw-chiffre\"> 1 an</span> <span class=\"q\">— souffle + signes associés</span></strong></p><p>prise en charge en <span class=\"kw-alerte\">urgence</span> — <span class=\"kw-ttt\">réanimation</span> + <span class=\"kw-ttt\">cardiopédiatrie</span></p><ul><li><span class=\"kw-alerte\">Cyanose</span> · <span class=\"kw-alerte\">insuffisance cardiaque</span> · <span class=\"kw-clinique\">polypnée</span></li></ul><p><strong><span class=\"kw-clinique\">Malaise</span> de Fallot <span class=\"q\">— complication aiguë de la T4F</span></strong></p><p><span class=\"kw-alerte\">urgence médicale voire chirurgicale</span></p><ul><li>Déclenché par une <span class=\"kw-clinique\">tachycardie</span> (<span class=\"kw-etio\">pleurs</span>, <span class=\"kw-etio\">effort</span>) → majoration de l'obstacle sous-valvulaire pulmonaire → ↑ du shunt droite-gauche</li><li><span class=\"kw-alerte\">Cyanose majeure</span></li></ul><p><strong>Cardiopathie ducto-dépendante <span class=\"q\">— <span class=\"kw-alerte\">décompensation</span> à la fermeture du canal artériel</span></strong></p><ul><li><span class=\"kw-etio\">Sténose pulmonaire critique</span> → <span class=\"kw-alerte\">cyanose réfractaire</span> majorée à la fermeture du canal</li><li><span class=\"kw-etio\">Rétrécissement aortique sévère</span> → <span class=\"kw-alerte\">choc cardiogénique</span> à la fermeture du canal</li><li><span class=\"kw-etio\">Coarctation préductale</span> → <span class=\"kw-alerte\">insuffisance cardiaque</span> néonatale grave</li></ul><p><strong>Transposition des gros vaisseaux <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> néonatale</span></strong></p><ul><li><span class=\"kw-alerte\">Cyanose réfractaire isolée</span> à la naissance, <span class=\"kw-alerte\">sans souffle</span></li><li>Survie dépendante de la perméabilité du <span class=\"kw-clinique\">foramen ovale</span> + <span class=\"kw-clinique\">canal artériel</span></li></ul><p><strong>Délais à respecter</strong></p><ul><li>Souffle isolé du <span class=\"kw-clinique\">nouveau-né</span> → <span class=\"kw-imagerie\">échocardiographie</span> avant sortie de maternité (ou avant <span class=\"kw-chiffre\">J8</span>)</li><li>Avant <span class=\"kw-chiffre\">1 an</span> → <span class=\"kw-imagerie\">échographie cardiaque</span> systématique, même pour un souffle isolé</li><li><span class=\"kw-etio\">Shunt gauche-droit</span> → opérer avant <span class=\"kw-chiffre\">1 an</span> (risque d'<span class=\"kw-alerte\">HTAP irréversible</span> si opéré trop tard)</li></ul>","hospit":"<p><strong>Nouveau-né / nourrisson &lt;<span class=\"kw-chiffre\"> 1 an</span> <span class=\"q\">— souffle souvent organique</span></strong></p><ul><li>Souffle + <span class=\"kw-alerte\">signes associés</span> (<span class=\"kw-clinique\">cyanose</span>, IC, polypnée) → <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-ttt\">réanimation</span> + <span class=\"kw-ttt\">cardiopédiatrie</span>)</li><li>Souffle isolé du nouveau-né → <span class=\"kw-imagerie\">échocardiographie</span> avant sortie de maternité (ou <span class=\"kw-chiffre\">&lt; J8</span>)</li><li>Souffle isolé du nourrisson → <span class=\"kw-ttt\">avis cardiopédiatrique</span> + <span class=\"kw-imagerie\">échocardiographie</span></li></ul><p><strong>Enfant &gt;<span class=\"kw-chiffre\"> 1 an</span> <span class=\"q\">— souffle souvent fonctionnel</span></strong></p><ul><li>Souffle isolé à <span class=\"kw-def\">caractéristiques fonctionnelles</span> → <span class=\"kw-clinique\">simple surveillance</span>, pas d'avis</li><li>Caractéristiques <span class=\"kw-alerte\">non fonctionnelles</span> ou <span class=\"kw-etio\">contexte familial</span> → <span class=\"kw-ttt\">avis cardiopédiatrique</span></li><li>Souffle non isolé + <span class=\"kw-alerte\">signes associés</span> → <span class=\"kw-alerte\">avis cardiopédiatrique urgent</span></li></ul><p><strong><span class=\"kw-imagerie\">Échocardiographie</span> systématique même sans souffle</strong></p><ul><li><span class=\"kw-etio\">Syndrome polymalformatif</span> (dysmorphie faciale, anomalie des extrémités / OGE)</li><li><span class=\"kw-etio\">Maladie génétique familiale</span> touchant le cœur ou <span class=\"kw-clinique\">les</span> gros vaisseaux (ex. <span class=\"kw-etio\">Marfan</span>)</li><li><span class=\"kw-etio\">Cardiopathie congénitale</span> chez un apparenté du 1ᵉʳ degré</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Souffle diastolique</span> → jamais fonctionnel</li><li><span class=\"kw-alerte\">Souffle holosystolique</span> → <span class=\"kw-etio\">CIV</span>, <span class=\"kw-etio\">insuffisance mitrale</span></li><li><span class=\"kw-alerte\">Souffle frémissant, tonalité râpeuse</span> → obstacle valvulaire (aortique / pulmonaire)</li><li><span class=\"kw-alerte\">Intensité maximale au bord gauche du thorax</span> (≠ sternum) → <span class=\"kw-etio\">coarctation</span></li><li><span class=\"kw-alerte\">Dédoublement fixe et constant du B2</span> → <span class=\"kw-etio\">CIA</span>, BBD</li><li><span class=\"kw-alerte\">Éclat du B2</span> au bord sternal gauche → <span class=\"kw-etio\">HTAP</span>, malposition des gros vaisseaux</li><li><span class=\"kw-alerte\">Click systolique</span> : mésosystolique apexien (prolapsus mitral) ; protosystolique (sténose valvulaire d'un gros vaisseau)</li><li><span class=\"kw-alerte\">Frémissement précordial ou sus-sternal</span> (thrill) → toujours pathologique</li><li><span class=\"kw-alerte\">Cyanose</span> à l'oxymétrie (<span class=\"kw-chiffre\">&lt; 85 %</span>), <span class=\"kw-alerte\">réfractaire à l'O₂</span> si cardiaque</li><li><span class=\"kw-alerte\">Gradient tensionnel &gt; 20 mmHg</span> (MS &gt; MI) → <span class=\"kw-etio\">coarctation</span></li><li><span class=\"kw-clinique\">Hépatomégalie</span> = marqueur constant d'<span class=\"kw-alerte\">insuffisance cardiaque</span></li><li><span class=\"kw-alerte\">Abolition des pouls fémoraux</span> → <span class=\"kw-etio\">coarctation</span> / <span class=\"kw-etio\">sténose aortique sévère</span></li></ul>","principes":"<p>Premier enjeu : distinguer le <span class=\"kw-def\">souffle fonctionnel</span> du <span class=\"kw-def\">souffle organique</span>. Au moindre doute → <span class=\"kw-imagerie\">échocardiographie</span> par un cardiopédiatre expérimenté.</p><p><strong>Souffle fonctionnel <span class=\"q\">— abstention thérapeutique</span></strong></p><ul><li><span class=\"kw-clinique\">Rassurer la famille</span></li><li><span class=\"kw-clinique\">Aucune surveillance</span> ni <span class=\"kw-clinique\">restriction sportive</span></li><li>Peut disparaître à l'adolescence ou persister à l'âge adulte</li></ul><p><strong>Cardiopathie <span class=\"kw-etio\">congénitale</span></strong></p><p><span class=\"kw-ttt\">suivi cardiopédiatrique à vie</span> planifié par le spécialiste référent</p><ul><li>Traitement définitif ou palliatif par <span class=\"kw-ttt\">chirurgie cardiaque</span> ou <span class=\"kw-ttt\">cathétérisme interventionnel</span></li><li><span class=\"kw-etio\">Shunt gauche-droit</span> → <span class=\"kw-ttt\">opérer avant 1 an</span> (éviter l'<span class=\"kw-alerte\">HTAP irréversible</span>)</li><li><span class=\"kw-etio\">Tétralogie de Fallot</span> → correction chirurgicale entre <span class=\"kw-chiffre\">6 mois et 1 an</span></li></ul>","suivi":"<p><strong><span class=\"kw-def\">Suivi</span> des cardiopathies congénitales</strong></p><ul><li><span class=\"kw-def\">Suivi</span> cardiopédiatrique <span class=\"kw-ttt\">à vie</span>, d'intensité variable selon <span class=\"kw-clinique\">les</span> lésions, planifié par le spécialiste référent</li><li><span class=\"kw-alerte\">Ruptures de suivi</span> fréquentes (conflit familial, déménagement, adolescence, oubli « quand tout va bien ») → réorienter</li><li>Persistance / réapparition d'un souffle → particularité anatomique, mais aussi <span class=\"kw-alerte\">lésion résiduelle</span> ou <span class=\"kw-alerte\">néolésion évolutive</span> → avis spécialisé</li><li>Activités sportives le plus souvent autorisées, à discuter avec le spécialiste référent</li></ul><p><strong><span class=\"kw-ttt\">Antibioprophylaxie</span> de l'<span class=\"kw-clinique\">endocardite</span> infectieuse</strong></p><ul><li>Lors des <span class=\"kw-ttt\">gestes dentaires à risque</span></li><li><span class=\"kw-etio\">Cardiopathie cyanogène</span> non opérée</li><li>Dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span> suivant la fermeture d'un shunt par <span class=\"kw-ttt\">patch / prothèse</span> (ou au-delà si shunt résiduel)</li></ul>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/pneumologie-cardiologie/souffle-cardiaque","label":"Pédia-univ — référentiel item 238 (souffle cardiaque)"},{"href":"https://www.sfcardio.fr/page/chapitre-11-item-238-souffle-cardiaque-chez-lenfant","label":"SFCardiologie — chapitre 11, item 238"}],"cards":[{"i":"244fa5cc2a21","n":238,"o":"238-1","u":"Diagnostic positif","t":"Connaître la sémiologie cardiovasculaire chez l’enfant","q":"Quelles sont les particularités de l'auscultation cardiaque chez l'enfant ?","a":"<p>Les particularités sont :</p><ul><li>L'enfant doit être <strong>calme et rassuré</strong> (par les parents).</li><li>Utilisation d'un <strong>stéthoscope pédiatrique</strong> avec membrane adaptée.</li><li>Le rythme cardiaque est souvent <strong>rapide et irrégulier</strong> (l'<strong>arythmie sinusale respiratoire</strong> est physiologique et parfois marquée).</li></ul>"},{"i":"4c0b52fcb8ea","n":238,"o":"238-1","u":"Diagnostic positif","t":"Connaître la sémiologie cardiovasculaire chez l’enfant","q":"Quels sont les signes cliniques cardiovasculaires qui peuvent être observés chez un nourrisson et orienter vers une cardiopathie congénitale ?","a":"<p>Chez le nourrisson, on peut observer :</p><ul><li><strong>Cyanose</strong> et/ou signes d'<strong>insuffisance cardiaque</strong>.</li><li><strong>Difficultés alimentaires</strong> (tétées longues, sudation, endormissement au sein).</li><li><strong>Retard staturo-pondéral</strong>.</li><li><strong>Polypnée</strong>.</li><li><strong>Infections pulmonaires</strong> à répétition.</li></ul>"},{"i":"65ee4827bbfa","n":238,"o":"238-1","u":"Diagnostic positif","t":"Connaître la sémiologie cardiovasculaire chez l’enfant","q":"Quels sont les signes cliniques généraux à rechercher systématiquement en présence d'un souffle cardiaque chez l'enfant, quel que soit l'âge ?","a":"<p>Il faut systématiquement rechercher :</p><ul><li>Une <strong>cyanose</strong>.</li><li>Des <strong>difficultés alimentaires</strong>.</li><li>Une <strong>symptomatologie à l'effort</strong> (dyspnée, douleurs, malaises, syncopes).</li></ul>"},{"i":"95fbad77dbb1","n":238,"o":"238-1","u":"Diagnostic positif","t":"Connaître la sémiologie cardiovasculaire chez l’enfant","q":"Quelles sont les caractéristiques permettant de décrire un souffle cardiaque chez l'enfant ?","a":"<p>Pour caractériser un souffle, il faut préciser :</p><ul><li>Son <strong>caractère</strong> (systolique, diastolique ou continu ; proto-, méso- ou télésystolique/diastolique).</li><li>Sa <strong>localisation</strong> (foyer où il est le mieux perçu).</li><li>Son <strong>timbre</strong> (aigu, grave, doux, râpeux, aspiratif, humide, sec, rude…).</li><li>Son <strong>intensité</strong> (de 1 à 6).</li><li>Son <strong>irradiation</strong> (espace de diffusion).</li><li>Les <strong>signes associés</strong> (clicks valvulaires, dédoublement constant du B2).</li></ul>"},{"i":"ea4acb8acee9","n":238,"o":"238-1","u":"Diagnostic positif","t":"Connaître la sémiologie cardiovasculaire chez l’enfant","q":"Quels sont les \"drapeaux rouges\" à l'auscultation orientant vers un souffle cardiaque pathologique chez l'enfant ?","a":"<p>Les drapeaux rouges excluant un souffle fonctionnel sont :</p><ul><li>Un souffle <strong>diastolique</strong>.</li><li>Un souffle <strong>holosystolique</strong> (orientant vers une CIV ou une insuffisance mitrale).</li><li>Un souffle <strong>frémissant</strong> ou à <strong>tonalité râpeuse</strong> (orientant vers un obstacle valvulaire aortique/pulmonaire).</li><li>Une intensité maximale au <strong>bord gauche du thorax</strong> (≠ sternum) (orientant vers une coarctation).</li><li>Un <strong>dédoublement fixe et constant du B2</strong> (orientant vers une CIA ou un BBD).</li><li>Un <strong>éclat du B2</strong> au bord sternal gauche (orientant vers une HTAP ou une malposition des gros vaisseaux).</li><li>Un <strong>click systolique</strong> (mésosystolique apexien pour un prolapsus mitral ; protosystolique pour une sténose valvulaire d'un gros vaisseau).</li></ul>"},{"i":"f9558d7d9798","n":238,"o":"238-1","u":"Diagnostic positif","t":"Connaître la sémiologie cardiovasculaire chez l’enfant","q":"Quels sont les six foyers d'auscultation cardiaque chez l'enfant ?","a":"<p>Les six foyers d'auscultation sont :</p><ul><li><strong>Pulmonaire</strong>.</li><li><strong>Aortique</strong>.</li><li><strong>Tricuspidien</strong> (xiphoïde).</li><li><strong>Mitral</strong> (apex).</li><li><strong>Sous-claviculaire gauche</strong>.</li><li><strong>Interscapulaire gauche</strong> (dos).</li></ul>"},{"i":"2ea4c6fb1130","n":238,"o":"238-2","u":"Définition","t":"Connaître la définition d’un souffle cardiaque organique et non organique","q":"Quelle est la définition d'un souffle cardiaque organique chez l'enfant ?","a":"<p>Un souffle cardiaque organique est créé par une <strong>anomalie morphologique cardiaque</strong> sous-jacente, le plus souvent d'origine <strong>congénitale</strong>. Un souffle intense peut traduire un <strong>gradient de pression anormal</strong> entre deux cavités (ex: petite CIV) ou entre deux parties d'un vaisseau (ex: coarctation).</p>"},{"i":"8c73cabe249e","n":238,"o":"238-2","u":"Définition","t":"Connaître la définition d’un souffle cardiaque organique et non organique","q":"Quelle est la définition d'un souffle cardiaque fonctionnel chez l'enfant ?","a":"<p>Un souffle cardiaque fonctionnel, également appelé <strong>innocent</strong> ou <strong>bénin</strong>, résulte de <strong>turbulences de l'écoulement normal du sang</strong> à travers le cœur et les vaisseaux. Il ne traduit <strong>pas d'anomalie morphologique</strong> cardiaque.</p>"}]};